PREFIX jolux: <http://data.legilux.public.lu/resource/ontology/jolux#>
SELECT DISTINCT ?work ?version ?start ?end ?expression ?xml WHERE {
 VALUES ?work { <https://fedlex.data.admin.ch/eli/cc/1952/1021_1046_1050>
<https://fedlex.data.admin.ch/eli/cc/1952/823_843_839>
<https://fedlex.data.admin.ch/eli/cc/1952/896_916_912>
<https://fedlex.data.admin.ch/eli/cc/1993/3043_3043_3043>
<https://fedlex.data.admin.ch/eli/cc/1993/3080_3080_3080>
<https://fedlex.data.admin.ch/eli/cc/2002/510>
<https://fedlex.data.admin.ch/eli/cc/2005/187>
<https://fedlex.data.admin.ch/eli/cc/2007/804>
<https://fedlex.data.admin.ch/eli/cc/2008/51>
<https://fedlex.data.admin.ch/eli/cc/2008/52>
<https://fedlex.data.admin.ch/eli/cc/2021/373>
<https://fedlex.data.admin.ch/eli/cc/2021/376> }
 ?version jolux:isMemberOf ?work; jolux:dateApplicability ?start.
 OPTIONAL { ?version jolux:dateEndApplicability ?end }
 OPTIONAL {
   ?version jolux:isRealizedBy ?expression.
   ?expression jolux:language <http://publications.europa.eu/resource/authority/language/DEU>;
     jolux:isEmbodiedBy ?manifestation.
   ?manifestation jolux:format <http://publications.europa.eu/resource/authority/file-type/XML>;
     jolux:isExemplifiedBy ?xml.
 }
 FILTER(str(?start) <= "2027-12-31" && (!BOUND(?end) || str(?end) >= "2026-01-01"))
} ORDER BY ?work ?start
